actions.script:
const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const userPartyId = ec.user.userAccount?.partyId || null
if (!partyId) partyId = userPartyId
const nowMillis = toMillis(ec.user.nowTimestamp)
const list = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', contactListId).one()
const evaluate = (pid) => {
    const out = {exists: false, isMailbox: false, isPublic: false, isArchived: false, postingEnumId: null, isMember: false,
        membershipStatusId: null, memberRoleTypeId: null, memberFromDate: null, deliveryEnumId: null, isOwner: false,
        canModerate: false, canSeeHeader: false, canReadAll: false, canReadOwn: false, canPost: false, canJoin: false}
    if (list == null) return out
    out.exists = true
    out.isMailbox = list.contactListTypeEnumId === 'MAILBOX'
    out.isPublic = list.isPublic === 'Y'
    out.postingEnumId = list.postingEnumId || 'ClpMembers'
    out.isArchived = list.archivedDate != null && toMillis(list.archivedDate) <= nowMillis
    // the party's current row: an accepted one first, then a pending request, then the latest
    let row = null
    if (pid) {
        const rows = Array.from(ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', contactListId)
                .condition('partyId', pid).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('-fromDate').list())
        row = rows.find((candidate) => candidate.statusId === 'CLPT_ACCEPTED') ||
                rows.find((candidate) => candidate.statusId === 'CLPT_PENDING') || rows[0] || null
    }
    out.membershipStatusId = row?.statusId ?? null
    out.isMember = out.membershipStatusId === 'CLPT_ACCEPTED'
    out.memberFromDate = row?.fromDate ?? null
    if (out.isMember) {
        out.memberRoleTypeId = row.roleTypeId || null
        out.deliveryEnumId = row.deliveryEnumId || list.defaultDeliveryEnumId || 'CldInbox'
    }
    out.isOwner = out.memberRoleTypeId === 'ListOwner'
    out.canModerate = out.isOwner || out.memberRoleTypeId === 'ListModerator'
    if (out.isMailbox) {
        out.canReadAll = out.isMember || (out.isPublic && out.postingEnumId !== 'ClpAnyUser')
        out.canReadOwn = out.canReadAll || (out.postingEnumId === 'ClpAnyUser' && !!pid)
        out.canSeeHeader = out.canReadOwn || out.isPublic || out.membershipStatusId === 'CLPT_PENDING'
        out.canPost = !out.isArchived && !!pid && (out.postingEnumId === 'ClpAnyUser' ||
                (out.postingEnumId === 'ClpModerators' ? out.canModerate : out.isMember))
    } else {
        out.canSeeHeader = true
        out.canPost = !out.isArchived
    }
    out.canJoin = !out.isArchived && !!pid && out.canSeeHeader && !out.isMember && out.membershipStatusId !== 'CLPT_PENDING'
    return out
}
let result = evaluate(partyId)
// another party's access is told only to a user who may see the mailbox
if (result.isMailbox && userPartyId && partyId !== userPartyId && !evaluate(userPartyId).canSeeHeader) result = evaluate(null)
exists = result.exists; isMailbox = result.isMailbox; isPublic = result.isPublic; isArchived = result.isArchived
postingEnumId = result.postingEnumId; isMember = result.isMember; membershipStatusId = result.membershipStatusId
memberRoleTypeId = result.memberRoleTypeId; memberFromDate = result.memberFromDate; deliveryEnumId = result.deliveryEnumId
isOwner = result.isOwner; canModerate = result.canModerate; canSeeHeader = result.canSeeHeader; canReadAll = result.canReadAll
canReadOwn = result.canReadOwn; canPost = result.canPost; canJoin = result.canJoin
contactList = canSeeHeader ? list.getMap() : null

const cf = ec.entity.conditionFactory
if (!partyId) partyId = ec.user.userAccount?.partyId || null
readableContactListIds = []
hiddenContactListIds = []
const mailboxes = Array.from(ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListTypeEnumId', 'MAILBOX')
        .selectField('contactListId').selectField('isPublic').selectField('postingEnumId').list())
if (mailboxes.length === 0) return
const memberOf = new Set(partyId ? Array.from(ec.entity.find('mantle.marketing.contact.ContactListParty')
        .condition('partyId', partyId).condition('statusId', 'CLPT_ACCEPTED')
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).selectField('contactListId').list())
        .map((row) => row.contactListId) : [])
for (const mailbox of mailboxes) {
    const readable = memberOf.has(mailbox.contactListId) ||
            (mailbox.isPublic === 'Y' && (mailbox.postingEnumId || 'ClpMembers') !== 'ClpAnyUser')
    if (readable) readableContactListIds.push(mailbox.contactListId)
    else hiddenContactListIds.push(mailbox.contactListId)
}

const creatorPartyId = ec.user.userAccount?.partyId || null
const isMailbox = contactListTypeEnumId === 'MAILBOX'
if (isMailbox && !creatorPartyId) { ec.message.addError('Creating a mailbox needs a user with a party'); return }
if (isMailbox) {
    if (!postingEnumId) postingEnumId = 'ClpMembers'
    if (!defaultDeliveryEnumId) defaultDeliveryEnumId = 'CldInbox'
}
const enumIn = (enumId, enumTypeId) => !enumId || ec.entity.find('moqui.basic.Enumeration').condition('enumId', enumId)
        .condition('enumTypeId', enumTypeId).useCache(true).one() != null
if (!enumIn(postingEnumId, 'ContactListPosting')) { ec.message.addError(`Unknown posting policy ${postingEnumId}`); return }
if (!enumIn(defaultDeliveryEnumId, 'ContactListDelivery')) { ec.message.addError(`Unknown delivery ${defaultDeliveryEnumId}`); return }
if (isPublic !== 'Y') isPublic = 'N'

contactListId = ec.service.sync().name('create#mantle.marketing.contact.ContactList').parameters({
    contactListTypeEnumId: contactListTypeEnumId, contactListName: contactListName, description: description,
    comments: comments, isPublic: isPublic, postingEnumId: postingEnumId, defaultDeliveryEnumId: defaultDeliveryEnumId,
    ownerPartyId: ownerPartyId, contactMechTypeEnumId: contactMechTypeEnumId, marketingCampaignId: marketingCampaignId}).call()?.contactListId
if (ec.message.hasError()) return

const now = ec.user.nowTimestamp
const addRow = (partyId, roleTypeId) => ec.service.sync().name('create#mantle.marketing.contact.ContactListParty').parameters({
    contactListId: contactListId, partyId: partyId, fromDate: now, statusId: 'CLPT_ACCEPTED', roleTypeId: roleTypeId}).call()
if (creatorPartyId) addRow(creatorPartyId, 'ListOwner')
const memberIds = memberPartyIdList == null ? [] : (typeof memberPartyIdList === 'string' ? memberPartyIdList.split(',') : Array.from(memberPartyIdList))
const added = new Set([creatorPartyId])
for (const memberId of memberIds.map((id) => String(id).trim()).filter((id) => id)) {
    if (ec.message.hasError()) return
    if (added.has(memberId)) continue
    added.add(memberId)
    addRow(memberId, null)
}

const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
        .parameter('contactListId', contactListId).call()
if (!access.exists || !access.canSeeHeader) { ec.message.addError(`Contact list ${contactListId} not found`); return }
if (access.isMailbox && !access.isOwner) { ec.message.addError('Only an owner of the mailbox may change it'); return }
const enumIn = (enumId, enumTypeId) => !enumId || ec.entity.find('moqui.basic.Enumeration').condition('enumId', enumId)
        .condition('enumTypeId', enumTypeId).useCache(true).one() != null
if (!enumIn(postingEnumId, 'ContactListPosting')) { ec.message.addError(`Unknown posting policy ${postingEnumId}`); return }
if (!enumIn(defaultDeliveryEnumId, 'ContactListDelivery')) { ec.message.addError(`Unknown delivery ${defaultDeliveryEnumId}`); return }
const list = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', contactListId).one()
const fields = {contactListName: contactListName, description: description, comments: comments,
    isPublic: isPublic == null ? null : (isPublic === 'Y' ? 'Y' : 'N'), postingEnumId: postingEnumId,
    defaultDeliveryEnumId: defaultDeliveryEnumId}
for (const [name, value] of Object.entries(fields)) if (value != null) list.set(name, value)
if (archived === true && list.archivedDate == null) list.set('archivedDate', ec.user.nowTimestamp)
if (archived === false) list.set('archivedDate', null)
list.update()

const cf = ec.entity.conditionFactory
const now = ec.user.nowTimestamp
const partyId = ec.user.userAccount?.partyId || null
contactListList = []
let find = ec.entity.find('mantle.marketing.contact.ContactList').orderBy('contactListName')
if (contactListTypeEnumId) find = find.condition('contactListTypeEnumId', contactListTypeEnumId)
if (searchText) find = find.condition(cf.makeCondition([cf.makeCondition('contactListName', 'like', `%${searchText}%`, false, true),
        cf.makeCondition('description', 'like', `%${searchText}%`, false, true)], 'or'))
if (!includeArchived) find = find.condition(cf.makeCondition('archivedDate', 'greater', now, true))
const lists = Array.from(find.list())
if (lists.length === 0) return
const listIds = lists.map((list) => list.contactListId)

const memberCounts = {}
for (const row of ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', 'in', listIds)
        .condition('statusId', 'CLPT_ACCEPTED').condition(cf.makeConditionDate('fromDate', 'thruDate', null))
        .selectField('contactListId').selectField('partyId').distinct(true).list())
    memberCounts[row.contactListId] = (memberCounts[row.contactListId] || 0) + 1

const entries = []
for (const list of lists) {
    const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
            .parameter('contactListId', list.contactListId).call()
    if (!access.canSeeHeader) continue
    if (memberOnly && !access.isMember && access.membershipStatusId !== 'CLPT_PENDING') continue
    entries.push({contactListId: list.contactListId, contactListTypeEnumId: list.contactListTypeEnumId ?? null,
        contactListName: list.contactListName ?? null, description: list.description ?? null, isPublic: list.isPublic ?? null,
        postingEnumId: access.postingEnumId, defaultDeliveryEnumId: list.defaultDeliveryEnumId ?? null,
        archivedDate: list.archivedDate ?? null, ownerPartyId: list.ownerPartyId ?? null, isMember: access.isMember,
        membershipStatusId: access.membershipStatusId ?? null, memberRoleTypeId: access.memberRoleTypeId ?? null,
        deliveryEnumId: access.deliveryEnumId ?? null, canPost: access.canPost, canModerate: access.canModerate,
        canJoin: access.canJoin, canReadAll: access.canReadAll, memberCount: memberCounts[list.contactListId] || 0,
        unreadCount: 0, lastPostDate: null, isMailbox: access.isMailbox})
}

// a mailbox's unread count and last post, for the mailboxes the user reads
const readIds = entries.filter((entry) => entry.isMailbox && entry.canReadAll).map((entry) => entry.contactListId)
if (readIds.length && partyId) {
    const unread = {}
    for (const row of ec.entity.find('mantle.party.communication.CommunicationEventPartyAndEvent').condition('partyId', partyId)
            .condition('contactListId', 'in', readIds).condition('roleTypeId', 'in', ['MessageTo', 'MessageCc', 'MessageMailbox'])
            .condition('readDate', null).condition('archivedDate', null).condition(cf.makeCondition('statusId', 'not-equals', 'CeCancelled', true))
            .selectField('contactListId').selectField('communicationEventId').distinct(true).list())
        unread[row.contactListId] = (unread[row.contactListId] || 0) + 1
    for (const entry of entries) {
        if (!readIds.includes(entry.contactListId)) continue
        entry.unreadCount = unread[entry.contactListId] || 0
        const last = ec.entity.find('mantle.party.communication.CommunicationEvent').condition('contactListId', entry.contactListId)
                .condition(cf.makeCondition('statusId', 'not-equals', 'CeCancelled', true)).selectField('entryDate')
                .orderBy('-entryDate').limit(1).list()
        entry.lastPostDate = last.length ? last[0].entryDate : null
    }
}
for (const entry of entries) delete entry.isMailbox
contactListList = entries

const cf = ec.entity.conditionFactory
memberList = []
pendingList = []
const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
        .parameter('contactListId', contactListId).call()
if (!access.exists || !access.canSeeHeader) { ec.message.addError(`Contact list ${contactListId} not found`); return }
if (access.isMailbox && !access.canReadAll && !access.isPublic) {
    ec.message.addError('Only the members of this mailbox may see its members'); return }
const list = access.contactList
const rows = Array.from(ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', contactListId)
        .condition('statusId', 'in', ['CLPT_ACCEPTED', 'CLPT_PENDING'])
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).orderBy('fromDate').list())
const partyIds = Array.from(new Set(rows.map((row) => row.partyId)))
const names = {}
if (partyIds.length) for (const party of ec.entity.find('mantle.party.PartyDetail').condition('partyId', 'in', partyIds)
        .disableAuthz().list())
    names[party.partyId] = party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.partyId
const roleOrder = {ListOwner: 0, ListModerator: 1}
const seen = new Set()
for (const row of rows) {
    const entry = {partyId: row.partyId, name: names[row.partyId] || row.partyId, roleTypeId: row.roleTypeId ?? null,
        deliveryEnumId: row.deliveryEnumId ?? null, effectiveDeliveryEnumId: row.deliveryEnumId || list.defaultDeliveryEnumId || 'CldInbox',
        statusId: row.statusId, fromDate: row.fromDate}
    if (row.statusId === 'CLPT_ACCEPTED') {
        if (seen.has(row.partyId)) continue
        seen.add(row.partyId)
        memberList.push(entry)
    } else if (access.canModerate) pendingList.push(entry)
}
pendingList = pendingList.filter((entry) => !seen.has(entry.partyId))
memberList.sort((a, b) => (roleOrder[a.roleTypeId] ?? 2) - (roleOrder[b.roleTypeId] ?? 2))

// the party's current row: an accepted one first, then a pending request, then the latest
const currentRow = (id) => {
    const rows = Array.from(ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', contactListId)
            .condition('partyId', id).condition(ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null))
            .orderBy('-fromDate').list())
    return rows.find((row) => row.statusId === 'CLPT_ACCEPTED') || rows.find((row) => row.statusId === 'CLPT_PENDING') || rows[0] || null
}
const partyId = ec.user.userAccount?.partyId || null
if (!partyId) { ec.message.addError('Joining a list needs a user with a party'); return }
const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
        .parameter('contactListId', contactListId).call()
// a private mailbox's header is hidden from those outside it, and a request by its id is still taken
if (!access.exists || (!access.canSeeHeader && !access.isMailbox)) { ec.message.addError(`Contact list ${contactListId} not found`); return }
if (access.isMember || access.membershipStatusId === 'CLPT_PENDING') {
    statusId = access.membershipStatusId; fromDate = access.memberFromDate; return }
if (access.isArchived) { ec.message.addError(`${access.contactList?.contactListName || contactListId} is archived`); return }
statusId = access.isPublic ? 'CLPT_ACCEPTED' : 'CLPT_PENDING'
const row = currentRow(partyId)
if (row != null) {
    // a current declined (or other) row: asked again
    row.set('statusId', statusId)
    row.update()
    fromDate = row.fromDate
    return
}
fromDate = ec.user.nowTimestamp
ec.service.sync().name('create#mantle.marketing.contact.ContactListParty').parameters({contactListId: contactListId,
    partyId: partyId, fromDate: fromDate, statusId: statusId}).call()

const cf = ec.entity.conditionFactory
endedCount = 0
const list = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', contactListId).one()
if (list == null) { ec.message.addError(`Contact list ${contactListId} not found`); return }
const current = Array.from(ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', contactListId)
        .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
const mine = current.filter((row) => row.partyId === partyId)
if (mine.length === 0) { ec.message.addError(`Party ${partyId} is not in ${list.contactListName || contactListId}`); return }
if (list.contactListTypeEnumId === 'MAILBOX' && mine.some((row) => row.statusId === 'CLPT_ACCEPTED' && row.roleTypeId === 'ListOwner')) {
    const accepted = current.filter((row) => row.statusId === 'CLPT_ACCEPTED')
    const otherOwners = accepted.filter((row) => row.roleTypeId === 'ListOwner' && row.partyId !== partyId)
    const otherMembers = accepted.filter((row) => row.partyId !== partyId)
    if (otherOwners.length === 0 && otherMembers.length > 0) {
        ec.message.addError('The last owner of a mailbox cannot leave it while it has other members; make another member an owner first')
        return
    }
}
for (const row of mine) {
    row.set('thruDate', ec.user.nowTimestamp)
    row.update()
    endedCount++
}

service.description:
An owner or moderator of a mailbox adds a member (CLPT_ACCEPTED) or accepts a pending or declined request;
for a member already in the list, the role and delivery given are set. Only an owner gives or changes a role
(ListOwner, ListModerator; empty is a member). Lists of other types are not checked here.

actions.script:
// the party's current row: an accepted one first, then a pending request, then the latest
const currentRow = (id) => {
    const rows = Array.from(ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', contactListId)
            .condition('partyId', id).condition(ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null))
            .orderBy('-fromDate').list())
    return rows.find((row) => row.statusId === 'CLPT_ACCEPTED') || rows.find((row) => row.statusId === 'CLPT_PENDING') || rows[0] || null
}
const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
        .parameter('contactListId', contactListId).call()
if (!access.exists || !access.canSeeHeader) { ec.message.addError(`Contact list ${contactListId} not found`); return }
const listName = access.contactList?.contactListName || contactListId
if (access.isMailbox && !access.canModerate) { ec.message.addError(`Only an owner or moderator of ${listName} may add members`); return }
if (access.isArchived) { ec.message.addError(`${listName} is archived`); return }
if (roleTypeId && !['ListOwner', 'ListModerator'].includes(roleTypeId)) {
    ec.message.addError(`A list member's role is ListOwner, ListModerator or empty, not ${roleTypeId}`); return }
if (roleTypeId && access.isMailbox && !access.isOwner) { ec.message.addError(`Only an owner of ${listName} may give a role`); return }
if (deliveryEnumId && ec.entity.find('moqui.basic.Enumeration').condition('enumId', deliveryEnumId)
        .condition('enumTypeId', 'ContactListDelivery').useCache(true).one() == null) {
    ec.message.addError(`Unknown delivery ${deliveryEnumId}`); return }
if (ec.entity.find('mantle.party.Party').condition('partyId', partyId).disableAuthz().one() == null) {
    ec.message.addError(`Party ${partyId} not found`); return }

statusId = 'CLPT_ACCEPTED'
const row = currentRow(partyId)
if (row != null) {
    const wasMember = row.statusId === 'CLPT_ACCEPTED'
    if (wasMember && row.roleTypeId && row.roleTypeId !== roleTypeId && access.isMailbox && !access.isOwner) {
        ec.message.addError(`Only an owner of ${listName} may change a role`); return }
    row.set('statusId', 'CLPT_ACCEPTED')
    if (!wasMember || access.isOwner || !access.isMailbox) row.set('roleTypeId', roleTypeId || null)
    if (deliveryEnumId) row.set('deliveryEnumId', deliveryEnumId)
    row.update()
    fromDate = row.fromDate
    return
}
fromDate = ec.user.nowTimestamp
ec.service.sync().name('create#mantle.marketing.contact.ContactListParty').parameters({contactListId: contactListId,
    partyId: partyId, fromDate: fromDate, statusId: statusId, roleTypeId: roleTypeId || null, deliveryEnumId: deliveryEnumId || null}).call()

const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
        .parameter('contactListId', contactListId).call()
if (!access.exists || !access.canSeeHeader) { ec.message.addError(`Contact list ${contactListId} not found`); return }
const listName = access.contactList?.contactListName || contactListId
if (access.isMailbox) {
    if (!access.canModerate) { ec.message.addError(`Only an owner or moderator of ${listName} may remove members`); return }
    const target = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
            .parameters({contactListId: contactListId, partyId: partyId}).call()
    if (target.isOwner && !access.isOwner) { ec.message.addError(`Only an owner of ${listName} may remove an owner`); return }
}
ec.service.sync().name('mantle.marketing.ContactListServices.end#ContactListParty')
        .parameters({contactListId: contactListId, partyId: partyId}).call()

// the party's current row: an accepted one first, then a pending request, then the latest
const currentRow = (id) => {
    const rows = Array.from(ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', contactListId)
            .condition('partyId', id).condition(ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null))
            .orderBy('-fromDate').list())
    return rows.find((row) => row.statusId === 'CLPT_ACCEPTED') || rows.find((row) => row.statusId === 'CLPT_PENDING') || rows[0] || null
}
const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
        .parameter('contactListId', contactListId).call()
if (!access.exists || !access.canSeeHeader) { ec.message.addError(`Contact list ${contactListId} not found`); return }
const listName = access.contactList?.contactListName || contactListId
if (access.isMailbox && !access.canModerate) { ec.message.addError(`Only an owner or moderator of ${listName} may decline a request`); return }
const row = currentRow(partyId)
if (row == null || row.statusId !== 'CLPT_PENDING') { ec.message.addError(`Party ${partyId} has no pending request for ${listName}`); return }
row.set('statusId', 'CLPT_REJECTED')
row.update()

// the party's current row: an accepted one first, then a pending request, then the latest
const currentRow = (id) => {
    const rows = Array.from(ec.entity.find('mantle.marketing.contact.ContactListParty').condition('contactListId', contactListId)
            .condition('partyId', id).condition(ec.entity.conditionFactory.makeConditionDate('fromDate', 'thruDate', null))
            .orderBy('-fromDate').list())
    return rows.find((row) => row.statusId === 'CLPT_ACCEPTED') || rows.find((row) => row.statusId === 'CLPT_PENDING') || rows[0] || null
}
const userPartyId = ec.user.userAccount?.partyId || null
if (!partyId) partyId = userPartyId
if (!partyId) { ec.message.addError('Setting a delivery needs a user with a party'); return }
if (deliveryEnumId && ec.entity.find('moqui.basic.Enumeration').condition('enumId', deliveryEnumId)
        .condition('enumTypeId', 'ContactListDelivery').useCache(true).one() == null) {
    ec.message.addError(`Unknown delivery ${deliveryEnumId}`); return }
const access = ec.service.sync().name('mantle.marketing.ContactListServices.get#ContactListAccess')
        .parameter('contactListId', contactListId).call()
if (!access.exists || !access.canSeeHeader) { ec.message.addError(`Contact list ${contactListId} not found`); return }
if (partyId !== userPartyId && access.isMailbox && !access.canModerate) {
    ec.message.addError('Only an owner or moderator may set another member\'s delivery'); return }
const row = currentRow(partyId)
if (row == null || row.statusId !== 'CLPT_ACCEPTED') {
    ec.message.addError(`Party ${partyId} is not a member of ${access.contactList?.contactListName || contactListId}`); return }
row.set('deliveryEnumId', deliveryEnumId || null)
row.update()
effectiveDeliveryEnumId = deliveryEnumId || access.contactList.defaultDeliveryEnumId || 'CldInbox'

const cf = ec.entity.conditionFactory
const CLP = 'mantle.marketing.contact.ContactListParty'
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const idOrder = (a, b) => (a.length - b.length) || (a < b ? -1 : a > b ? 1 : 0)
const newestFirst = (a, b) => ((toMillis(b.consentDate) ?? 0) - (toMillis(a.consentDate) ?? 0)) ||
        idOrder(String(b.partyConsentId), String(a.partyConsentId))
communicationEventId = null; sentCount = 0; recipientList = []; skippedList = []; failedPartyIdList = []
const nowMillis = toMillis(ec.user.nowTimestamp)
const currentDate = cf.makeConditionDate('fromDate', 'thruDate', null)

const list = ec.entity.find('mantle.marketing.contact.ContactList').condition('contactListId', contactListId).one()
if (list == null) { ec.message.addError(`Contact list ${contactListId} not found`); return }
const listName = list.contactListName || contactListId
if (list.contactListTypeEnumId === 'MAILBOX') { ec.message.addError(`${listName} is a mailbox: post to it instead`); return }
if (list.archivedDate != null && toMillis(list.archivedDate) <= nowMillis) { ec.message.addError(`${listName} is archived`); return }
if (list.contactMechTypeEnumId && list.contactMechTypeEnumId !== 'CmtEmailAddress') { ec.message.addError(`${listName} is not a list of email addresses`); return }
if (!emailTemplateId) emailTemplateId = Array.from(ec.entity.find('mantle.marketing.contact.ContactListEmail').condition('contactListId', contactListId)
        .condition('emailTypeEnumId', 'CONT_EMAIL_TEMPLATE').condition(currentDate).orderBy('-fromDate').list()).map((row) => row.emailTemplateId).find((id) => id) || null
if (!emailTemplateId) { ec.message.addError(`${listName} has no email template: give emailTemplateId or add its Outgoing Email`); return }
const template = ec.entity.find('moqui.basic.email.EmailTemplate').condition('emailTemplateId', emailTemplateId).one()
if (template == null) { ec.message.addError(`Email template ${emailTemplateId} not found`); return }
// the site address: baseUrl, the template's web host name, its email server's web base URL, the conf webapp's
// URL; never the host of a request, and never localhost, which a whole list would get as a dead link
let root = String(baseUrl || '').trim()
if (!root && template.webHostName) root = `https://${template.webHostName}`
if (!root && template.emailServerId) root = String(ec.entity.find('moqui.basic.email.EmailServer')
        .condition('emailServerId', template.emailServerId).useCache(true).one()?.webBaseUrl || '').trim()
if (!root) { try { root = ec.web ? String(ec.web.getWebappRootUrl(true, null) || '') : '' } catch (err) { root = '' } }
if (/^https?:\/\/(localhost|127\.0\.0\.1)([:\/]|$)/i.test(root)) root = ''
if (!root) { ec.message.addError('The unsubscribe links need the site address: give baseUrl, the template\'s web host name or its email server\'s web base URL'); return }
let organizationName = null
if (list.ownerPartyId) {
    const owner = ec.entity.find('mantle.party.PartyDetail').condition('partyId', list.ownerPartyId).one()
    organizationName = owner == null ? null : (owner.organizationName || ec.resource.expand('PartyFullNameTemplate', '', owner).trim() || null)
}

// the subscribed members, each party once
const only = partyIdList ? new Set(Array.from(partyIdList).map((id) => String(id))) : null
const memberRows = Array.from(ec.entity.find(CLP).condition('contactListId', contactListId).condition(currentDate)
        .condition('statusId', 'in', ['CLPT_ACCEPTED', 'CLPT_IN_USE']).orderBy('-fromDate').list())
        .filter((row) => only == null || only.has(row.partyId))
// each party's latest row, the members in the order they joined (then by id), so an address two share goes to the first
const byParty = new Map()
for (const row of memberRows) if (!byParty.has(row.partyId)) byParty.set(row.partyId, row)
const joined = (row) => toMillis(row.fromDate) ?? 0
const members = Array.from(byParty.entries()).sort(([a, left], [b, right]) => (joined(left) - joined(right)) || idOrder(String(a), String(b)))
const skip = (partyId, contactMechId, reason) => skippedList.push({partyId: partyId, contactMechId: contactMechId || null, reason: reason})
const recipients = []
const addresses = new Set()
for (const [partyId, row] of members) {
    const party = ec.entity.find('mantle.party.Party').condition('partyId', partyId).one()
    if (party == null || party.disabled === 'Y' || party.mergedToPartyId) { skip(partyId, null, 'disabled or merged'); continue }
    const infos = Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', partyId)
            .condition('contactMechTypeEnumId', 'CmtEmailAddress').condition(currentDate).orderBy('fromDate').list()).filter((info) => info.infoString)
    const preferred = row.preferredContactMechId ? infos.find((info) => info.contactMechId === row.preferredContactMechId) : null
    const address = preferred || infos.find((info) => info.contactMechPurposeId === 'EmailPrimary') || infos[0] || null
    if (address == null) { skip(partyId, null, 'no email address'); continue }
    const flags = infos.filter((info) => info.contactMechId === address.contactMechId).map((info) => info.allowSolicitation)
    if (flags.includes('N') && !flags.includes('Y')) { skip(partyId, address.contactMechId, 'does not allow solicitation'); continue }
    const consents = Array.from(ec.entity.find('mantle.party.PartyConsent').condition('partyId', partyId)
            .condition('purposeEnumId', 'PcpMarketingEmail').condition('contactListId', null).list())
    consents.sort(newestFirst)
    const forAddress = consents.find((consent) => consent.contactMechId === address.contactMechId)
    const forParty = consents.find((consent) => !consent.contactMechId)
    if (forAddress?.statusId === 'PconWithdrawn' || (!forAddress && forParty?.statusId === 'PconWithdrawn')) {
        skip(partyId, address.contactMechId, 'marketing email withdrawn'); continue }
    const key = String(address.infoString).trim().toLowerCase()
    if (addresses.has(key)) { skip(partyId, address.contactMechId, 'address already sent to'); continue }
    addresses.add(key)
    recipients.push({partyId: partyId, contactMechId: address.contactMechId, emailAddress: address.infoString})
}

// the send's communication event, committed (in a transaction of its own, when the caller has one) before the
// members' rows refer to it from theirs
communicationEventId = ec.service.sync().name('create#mantle.party.communication.CommunicationEvent').requireNewTransaction(true).parameters({
    communicationEventTypeId: 'Email', contactMechTypeEnumId: 'CmtEmailAddress', statusId: 'CeSent', fromPartyId: list.ownerPartyId || null,
    contactListId: contactListId, subject: subject || template.subject || listName, contentType: body ? 'text/html' : (bodyText ? 'text/plain' : null),
    body: body || bodyText || null, entryDate: ec.user.nowTimestamp, datetimeStarted: ec.user.nowTimestamp}).call()?.communicationEventId ?? null
if (ec.message.hasError() || !communicationEventId) return

for (const recipient of recipients) {
    try {
        const out = ec.service.sync().name('mantle.marketing.ContactListServices.send#ContactListPartyEmail').parameters({
            contactListId: contactListId, communicationEventId: communicationEventId, partyId: recipient.partyId,
            contactMechId: recipient.contactMechId, emailAddress: recipient.emailAddress, emailTemplateId: emailTemplateId,
            body: body || null, bodyText: bodyText || null, bodyParameters: bodyParameters || null, baseUrl: root,
            unsubscribeMailto: unsubscribeMailto || null, validDays: validDays || null, contactListName: listName,
            organizationName: organizationName}).requireNewTransaction(true).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        recipientList.push(Object.assign({}, recipient, {emailMessageId: out.emailMessageId ?? null, messageId: out.messageId ?? null,
            unsubscribeUrl: out.unsubscribeUrl ?? null, listUnsubscribeHeaders: out.listUnsubscribeHeaders ?? null}))
        sentCount++
    } catch (err) {
        ec.message.clearErrors()
        ec.logger.error(`List email ${communicationEventId} of list ${contactListId} to party ${recipient.partyId} failed: ${String(err && err.message ? err.message : err).trim()}`)
        failedPartyIdList.push(recipient.partyId)
    }
}
ec.service.sync().name('update#mantle.party.communication.CommunicationEvent').parameters({communicationEventId: communicationEventId,
    datetimeEnded: ec.user.nowTimestamp}).call()

const link = ec.service.sync().name('mantle.party.ConsentServices.create#UnsubscribeToken').parameters({contactListId: contactListId,
    partyId: partyId, contactMechId: contactMechId, communicationEventId: communicationEventId, baseUrl: baseUrl || null,
    mailtoAddress: unsubscribeMailto || null, validDays: validDays || null}).call()
if (ec.message.hasError()) return
unsubscribeUrl = link.unsubscribeUrl
listUnsubscribeHeaders = link.listUnsubscribeHeaders
const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', partyId).one()
const params = Object.assign({}, bodyParameters || {}, {partyId: partyId, firstName: party?.firstName ?? null, lastName: party?.lastName ?? null,
    partyName: party == null ? null : (ec.resource.expand('PartyFullNameTemplate', '', party).trim() || null), contactListId: contactListId,
    contactListName: contactListName || contactListId, organizationName: organizationName || null, communicationEventId: communicationEventId,
    unsubscribeUrl: unsubscribeUrl, listUnsubscribeHeaders: listUnsubscribeHeaders})
const encode = (text) => String(text == null ? '' : text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
// ${name} of the parameters in a given body (HTML-encoded there), and the unsubscribe footer when the body has no link
const expand = (text, html) => String(text).replace(/\$\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}/g, (whole, name) =>
        Object.prototype.hasOwnProperty.call(params, name) ? (html ? encode(params[name]) : String(params[name] ?? '')) : whole)
const footerName = encode(params.contactListName)
let html = body ? expand(body, true) : null
if (html && !html.includes(unsubscribeUrl)) html += `<p style="font-size:12px;color:#666666">You receive this email because you subscribed to ${footerName}.`
        + ` <a href="${encode(unsubscribeUrl)}">Unsubscribe</a></p>`
let text = bodyText ? expand(bodyText, false) : null
if (text && !text.includes(unsubscribeUrl)) text += `\n\n--\nYou receive this email because you subscribed to ${params.contactListName}. Unsubscribe: ${unsubscribeUrl}\n`
const out = ec.service.sync().name('org.moqui.impl.EmailServices.send#EmailTemplate').parameters({emailTemplateId: emailTemplateId,
    toAddresses: emailAddress, body: html, bodyText: text, bodyParameters: params, extraHeaders: listUnsubscribeHeaders,
    createEmailMessage: true}).call()
if (ec.message.hasError()) return
emailMessageId = out?.emailMessageId || null
messageId = out?.messageId || null
ec.service.sync().name('store#mantle.marketing.contact.ContactListCommStatus').parameters({contactListId: contactListId,
    communicationEventId: communicationEventId, contactMechId: contactMechId, partyId: partyId, messageId: messageId,
    statusId: messageId ? 'CeSent' : 'CeReady'}).call()
if (ec.message.hasError()) return
if (messageId) {
    const tokenRow = ec.entity.find('mantle.marketing.contact.ContactListToken').condition('contactListTokenId', link.contactListTokenId).one()
    if (tokenRow != null) { tokenRow.set('messageId', messageId); tokenRow.update() }
}
